INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist es wahr, dass ein wirtschaftlicher Abschwung immer Arbeitslosigkeit erhöht?', 2, '[{"text": "Nein", "correct": true, "because": "Hängt von Struktur und Dauer ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was definiert einen wirtschaftlichen Rückgang technisch?', 3, '[{"text": "BIP-Rückgang zwei Quartale", "correct": true, "because": "Standarddefinition"}, {"text": "Börsensturz", "correct": false, "because": "Nur ein Symptom"}, {"text": "Inflationsanstieg", "correct": false, "because": "Anderes Phänomen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können einen Wirtschaftsabschwung auslösen?', 5, '[{"text": "Hohe Zinsen", "correct": true, "because": "Bremsen Investitionen"}, {"text": "Nachfragerückgang", "correct": true, "because": "Reduziert Umsätze"}, {"text": "Steigende Löhne", "correct": false, "because": "Eher sekundär"}, {"text": "Bürokratieabbau", "correct": false, "because": "Fördert Wachstum"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein BIP-Rückgang definiert einen Abschwung. b) Inflation verhindert ihn immer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Inflation kann koexistieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Analyse einer Wirtschaftskrise?', 4, '[{"text": "Konsumverhalten", "correct": false, "because": "Treibt Nachfrage"}, {"text": "Zinssätze", "correct": false, "because": "Beeinflussen Investitionen"}, {"text": "Währungsfarbe", "correct": true, "because": "Kein wirtschaftlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Abschwung immer global ist?', 2, '[{"text": "Nein", "correct": true, "because": "Kann regional sein"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig global"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme kann einen Abschwung abmildern?', 4, '[{"text": "Leitzinssenkung", "correct": true, "because": "Fördert Kredite"}, {"text": "Steuererhöhung", "correct": false, "because": "Bremst Konsum"}, {"text": "Exportstopp", "correct": false, "because": "Schadet Wirtschaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Abschwung immer Insolvenzen auslöst. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Hängt von Schwere ab"}, {"text": "Ja", "correct": false, "because": "Nicht automatisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Rückgang der Exporte immer die Hauptursache?', 2, '[{"text": "Nein", "correct": true, "because": "Viele Faktoren möglich"}, {"text": "Ja", "correct": false, "because": "Nur ein möglicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Indikatoren zeigen einen Wirtschaftsabschwung an?', 5, '[{"text": "Sinkendes BIP", "correct": true, "because": "Kernindikator"}, {"text": "Steigende Arbeitslosigkeit", "correct": true, "because": "Häufiges Symptom"}, {"text": "Höhere Zinsen", "correct": false, "because": "Eher Ursache"}, {"text": "Bunte Aktiencharts", "correct": false, "because": "Kein Indikator"}]'),
('00000000-0000-0000-0000-000000000000', 'Was würdest du priorisieren, um eine Krise zu bekämpfen?', 4, '[{"text": "Investitionsanreize", "correct": true, "because": "Fördert Wachstum"}, {"text": "Konsumverbote", "correct": false, "because": "Schadet Nachfrage"}, {"text": "Höhere Bürokratie", "correct": false, "because": "Bremst Unternehmen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Rezessionen sind zyklisch. b) Sie dauern immer Jahre.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) ist falsch, Dauer variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht, um einen Abschwung zu analysieren?', 3, '[{"text": "BIP-Daten", "correct": false, "because": "Zentraler Indikator"}, {"text": "Arbeitslosenquote", "correct": false, "because": "Wichtiges Signal"}, {"text": "Währungsdesign", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, wie ich eine Krise erkenne?', 4, '[{"text": "BIP-Rückgang prüfen", "correct": true, "because": "Technische Definition"}, {"text": "Nur Börse beobachten", "correct": false, "because": "Zu eingeschränkt"}, {"text": "Wetterdaten analysieren", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Abschwung immer durch Inflation ausgelöst wird. Stimmt das?', 3, '[{"text": "Nein", "correct": true, "because": "Verschiedene Ursachen möglich"}, {"text": "Ja", "correct": false, "because": "Nur eine mögliche Ursache"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip hilft, die Auswirkungen einer Krise zu minimieren?', 4, '[{"text": "Fiskalpolitik", "correct": true, "because": "Regt Nachfrage an"}, {"text": "Konsumstopp", "correct": false, "because": "Verschärft Krise"}, {"text": "Exportverbote", "correct": false, "because": "Schadet Handel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann ein Abschwung nur lokal sein?', 2, '[{"text": "Ja", "correct": true, "because": "Kann ein Land betreffen"}, {"text": "Nein", "correct": false, "because": "Nicht immer global"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Branchen sind oft von einer Krise betroffen?', 5, '[{"text": "Baugewerbe", "correct": true, "because": "Sensitiv für Investitionen"}, {"text": "Industrie", "correct": true, "because": "Nachfragerückgang"}, {"text": "IT-Dienste", "correct": false, "because": "Weniger betroffen"}, {"text": "Marketing", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Krisenbewältigung unwichtig?', 3, '[{"text": "Staatliche Anreize", "correct": false, "because": "Fördern Erholung"}, {"text": "Zinssenkungen", "correct": false, "because": "Regen Investitionen an"}, {"text": "Firmenlogos", "correct": true, "because": "Kein wirtschaftlicher Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie gehe ich vor, wenn ich die Tiefe einer Krise bewerten will?', 4, '[{"text": "BIP, Arbeitslosigkeit prüfen", "correct": true, "because": "Zeigen Schweregrad"}, {"text": "Nur Aktienkurse", "correct": false, "because": "Zu volatil"}, {"text": "Social Media analysieren", "correct": false, "because": "Unzuverlässig"}]');
